/** Direct, live sub-issues, oldest first by creation time then issue number. */
export async function listDirectSubIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.parentId, issueId),
        isNull(issues.archivedAt),
      ),
    )
    .orderBy(issues.createdAt, issues.number)
    .all();

  const labels = await listLabelsForIssues(orgId, rows.map((row) => row.id as IssueId));
  return rows.map((row) => toIssue(row, (labels[row.id] ?? []).map((l) => l.id)));
}

/**
 * Every live issue below `issueId`, at any depth, breadth-first. Archived
 * branches are never descended into: an issue cannot gain a live child once
 * archived, so there is nothing live beneath one.
 */
export async function listLiveDescendants(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const result: Issue[] = [];
  let frontier: IssueId[] = [issueId];

  while (frontier.length > 0) {
    const rows = getDb()
      .select()
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.parentId, frontier),
          isNull(issues.archivedAt),
        ),
      )
      .all();
    if (rows.length === 0) break;

    frontier = rows.map((row) => row.id as IssueId);
    result.push(...rows.map((row) => toIssue(row)));
  }

  return result;
}

/**
 * The full set of descendant ids below `issueId` (any status, any depth) and
 * the height of that subtree, in one breadth-first pass. Used to judge a move
 * against the cycle and max-depth invariants — both a candidate cycle and a
 * candidate's deepest descendant are relative to this same subtree.
 */
export async function loadSubtreeShape(
  orgId: OrgId,
  issueId: IssueId,
): Promise<{ readonly descendantIds: ReadonlySet<IssueId>; readonly height: number }> {
  const descendantIds = new Set<IssueId>();
  let frontier: IssueId[] = [issueId];
  let height = 0;

  while (true) {
    const rows = getDb()
      .select({ id: issues.id })
      .from(issues)
      .where(
        and(orgPredicate(issues.orgId, orgId), inArray(issues.parentId, frontier)),
      )
      .all();
    if (rows.length === 0) break;

    frontier = rows.map((row) => row.id as IssueId);
    for (const id of frontier) descendantIds.add(id);
    height += 1;
  }

  return { descendantIds, height };
}

/** Level of `issueId` in its tree: a root issue is level 0. */
export async function findIssueLevel(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  let level = 0;
  let currentId: IssueId | null = issueId;

  while (currentId !== null) {
    const row = getDb()
      .select({ parentId: issues.parentId })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, currentId)))
      .get();
    if (!row || row.parentId === null) break;
    level += 1;
    currentId = row.parentId as IssueId;
  }

  return level;
}

export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

