/** Level of `issueId` in its tree: a root issue is level 0. */
export async function findIssueLevel(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  let level = 0;
  let currentId: IssueId | null = issueId;

  while (currentId !== null) {
    const row = getDb()
      .select({ parentId: issues.parentId })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, currentId)))
      .get();
    if (!row || row.parentId === null) break;
    level += 1;
    currentId = row.parentId as IssueId;
  }

  return level;
}

export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

