/**
 * Archiving cascades to every live issue below, at any depth — each gets its
 * own `issue.archived` event so the counter, search index and alerts that
 * react to it fire for all of them, not just the issue named here. The
 * archived issues' own ancestors are never touched.
 */
export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const descendants = await issueRepo.listLiveDescendants(orgId, issueId);
  const toArchive = [issue, ...descendants];

  // Archive the whole subtree before running any completion checks: a check
  // against a parent outside the subtree must see every descendant's final
  // (archived) state, not a half-cascaded one.
  const archivedById = new Map<IssueId, Issue>();
  for (const target of toArchive) {
    const archived = await issueRepo.archiveIssue(orgId, target.id);
    archivedById.set(target.id, archived);
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: archived.id,
      projectId: archived.projectId,
    });
  }

  for (const target of toArchive) {
    if (!CLOSED_ISSUE_STATUSES.includes(target.status)) {
      await notifyParentIfFullyClosed(actor, target);
    }
  }

  const archived = archivedById.get(issue.id);
  if (!archived) throw new Error(`Issue ${issueId} not found`);
  return archived;
}

/**
 * Tells a parent's assignee once, the moment its last open sub-issue closes.
 * Only the direct parent is considered; a parent with no assignee, an
 * archived parent, or one with no sub-issues left open already is silent.
 */
async function notifyParentIfFullyClosed(
  actor: Actor,
  closedIssue: Issue,
): Promise<void> {
  if (closedIssue.parentId === null) return;

  const parent = await issueRepo.findIssueById(
    closedIssue.orgId,
    closedIssue.parentId,
  );
  if (parent === null) return;
  if (parent.archivedAt !== null) return;
  if (parent.assigneeId === null) return;

  const remaining = await issueRepo.listLiveDescendants(
    closedIssue.orgId,
    parent.id,
  );
  const stillOpen = remaining.some(
    (descendant) => !CLOSED_ISSUE_STATUSES.includes(descendant.status),
  );

