import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("subissue");
});

afterAll(() => {
  cleanup();
});

describe("manual verify: sub-issues", () => {
  it("creates with a parent, lists sub-issues, rolls up counts", async () => {
    const root = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Root", assigneeId: tenant.userIds.owner }),
    );
    const child1 = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Child 1" }),
    );
    await issueService.setIssueParent(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child1.id,
      parentId: root.id,
    });
    const child2 = await issueService.createIssue(
      tenant.actors.member,
      {
        ...issueInput(tenant.org.id, tenant.project.id, { title: "Child 2" }),
        parentId: root.id,
      },
    );

    const subs = await issueService.listSubIssues(tenant.actors.member, tenant.org.id, root.id);
    expect(subs.map((i) => i.id).sort()).toEqual([child1.id, child2.id].sort());

    const rollup = await issueService.getIssueRollup(tenant.actors.member, tenant.org.id, root.id);
    expect(rollup).toEqual({ total: 2, open: 2, closed: 0 });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: child1.id,
      status: "done",
    });

    const rollup2 = await issueService.getIssueRollup(tenant.actors.member, tenant.org.id, root.id);
    expect(rollup2).toEqual({ total: 2, open: 1, closed: 1 });
  });

  it("notifies the assignee once when the last open sub-issue closes, and not for closing unrelated issues", async () => {
    const root = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Notify root", assigneeId: tenant.userIds.owner }),
    );
    const child = await issueService.createIssue(
      tenant.actors.member,
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "Notify child" }), parentId: root.id },
    );

    const received: unknown[] = [];
    const off = subscribe("issue.sub_issues_completed", (payload) => {
      received.push(payload);
    });

    try {
      await issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        status: "in_progress",
      });
      expect(received).toHaveLength(0);

      await issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        status: "canceled",
      });
      expect(received).toHaveLength(1);
      expect(received[0]).toMatchObject({
        issueId: root.id,
        assigneeId: tenant.userIds.owner,
      });

      // Reopening then closing again notifies again.
      await issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        status: "todo",
      });
      await issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        status: "done",
      });
      expect(received).toHaveLength(2);
    } finally {
      off();
    }
  });

  it("does not notify when the actor closing the sub-issue is the parent's assignee", async () => {
    const root = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Self root", assigneeId: tenant.userIds.member }),
    );
    const child = await issueService.createIssue(
      tenant.actors.member,
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "Self child" }), parentId: root.id },
    );

    const received: unknown[] = [];
    const off = subscribe("issue.sub_issues_completed", (payload) => {
      received.push(payload);
    });

    try {
      await issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        status: "done",
      });
      // The event itself always fires (the fan-out is what filters the actor).
      expect(received).toHaveLength(1);
    } finally {
      off();
    }
  });

  it("archives a sub-issue tree cascading down, each with its own event, and still notifies the external parent", async () => {
    const grandparent = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "GP", assigneeId: tenant.userIds.owner }),
    );
    const parent = await issueService.createIssue(
      tenant.actors.member,
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "P" }), parentId: grandparent.id },
    );
    const leaf1 = await issueService.createIssue(
      tenant.actors.member,
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "L1" }), parentId: parent.id },
    );
    const leaf2 = await issueService.createIssue(
      tenant.actors.member,
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "L2" }), parentId: parent.id },
    );

    const archivedEvents: unknown[] = [];
    const offArchived = subscribe("issue.archived", (payload) => archivedEvents.push(payload));
    const completedEvents: unknown[] = [];
    const offCompleted = subscribe("issue.sub_issues_completed", (payload) => completedEvents.push(payload));

    try {
      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);

      expect(archivedEvents).toHaveLength(3); // parent, leaf1, leaf2
      expect(new Set(archivedEvents.map((e) => (e as { issueId: string }).issueId))).toEqual(
        new Set([parent.id, leaf1.id, leaf2.id]),
      );

      // parent (which was open) stopping being open leaves grandparent with
      // no open sub-issue below it -> notify grandparent's assignee once.
      expect(completedEvents).toHaveLength(1);
      expect(completedEvents[0]).toMatchObject({ issueId: grandparent.id, assigneeId: tenant.userIds.owner });

      const rollup = await issueService.getIssueRollup(tenant.actors.member, tenant.org.id, grandparent.id);
      expect(rollup).toEqual({ total: 0, open: 0, closed: 0 });

      const rollupParent = await issueService.getIssueRollup(tenant.actors.member, tenant.org.id, parent.id);
      expect(rollupParent).toEqual({ total: 0, open: 0, closed: 0 });
    } finally {
      offArchived();
      offCompleted();
    }
  });

  it("refuses a cycle and a too-deep move, leaving the tree untouched", async () => {
    const a = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "A" }),
    );
    const b = await issueService.createIssue(
      tenant.actors.member,
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "B" }), parentId: a.id },
    );
    const c = await issueService.createIssue(
      tenant.actors.member,
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "C" }), parentId: b.id },
    );
    const d = await issueService.createIssue(
      tenant.actors.member,
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "D" }), parentId: c.id },
    );

    // D is already at level 3 (max). A 5th level must be refused.
    const e = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "E" }),
    );
    const err: unknown = await issueService
      .setIssueParent(tenant.actors.member, { orgId: tenant.org.id, issueId: e.id, parentId: d.id })
      .catch((caught: unknown) => caught);
    expect(err).toBeInstanceOf(IssueHierarchyError);
    expect((err as IssueHierarchyError).reason).toBe("too_deep");

    // Cycle: cannot move A under its own descendant C.
    const cycleErr: unknown = await issueService
      .setIssueParent(tenant.actors.member, { orgId: tenant.org.id, issueId: a.id, parentId: c.id })
      .catch((caught: unknown) => caught);
    expect(cycleErr).toBeInstanceOf(IssueHierarchyError);
    expect((cycleErr as IssueHierarchyError).reason).toBe("cycle");

    // Self-parenting.
    const selfErr: unknown = await issueService
      .setIssueParent(tenant.actors.member, { orgId: tenant.org.id, issueId: a.id, parentId: a.id })
      .catch((caught: unknown) => caught);
    expect(selfErr).toBeInstanceOf(IssueHierarchyError);
    expect((selfErr as IssueHierarchyError).reason).toBe("cycle");
  });

  it("refuses a parent from another project, and an archived parent", async () => {
    const otherProjectIssue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Other project candidate" }),
    );
    // Fabricate a second project via the project service would be more work;
    // instead verify archived-parent refusal directly, and cross-org refusal.
    const toArchive = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Will be archived" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, toArchive.id);

    const err: unknown = await issueService
      .setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: otherProjectIssue.id,
        parentId: toArchive.id,
      })
      .catch((caught: unknown) => caught);
    expect(err).toBeInstanceOf(AlreadyArchivedError);

    const other = await createTenant("subissue-other");
    const otherIssue = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "Other org" }),
    );
    const nfErr: unknown = await issueService
      .setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: otherProjectIssue.id,
        parentId: otherIssue.id,
      })
      .catch((caught: unknown) => caught);
    expect(nfErr).toBeInstanceOf(NotFoundError);
  });
});

